(()=>{const records=[["Thmanyah Sans","400",""],["Thmanyah Sans","500",""],["Thmanyah Sans","700",""],["Thmanyah Serif Display","500",""],["Thmanyah Serif Display","700",""]];window.EWAN_FONTS_READY=Promise.all(records.map(([family,weight,payload])=>{const binary=atob(payload);const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)^91);const face=new FontFace(family,bytes.buffer,{weight,style:'normal',display:'swap'});document.fonts.add(face);return face.load();}));window.EWAN_FONTS_READY.catch(()=>{});})();
